    {
        CPSCRenderMesh m; m.BankIndex = 1; m.CentredOnPos = 0; m.UseRenderSizeParam = 1; m.RenderSizeParam = 9;
        CParticleUpdateParameters<unsigned long, unsigned long> p; p.Has = true; p.Key = 9; p.Val = C3DVector(2, 4, 8);
